CREATE OR REPLACE FUNCTION combat_consumer_private.scene_snapshot_v2(p_claim uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c combat_consumer_private.narrative_claims%ROWTYPE;
  activity combat_consumer_private.activities%ROWTYPE; row record; snap jsonb; candidate jsonb;
  actors jsonb; actions jsonb:='[]'; sources jsonb:='[]'; role_count integer:=0;
  prior_count integer:=0; included integer:=0; current_round integer; place public.locations%ROWTYPE;
  body_sha text; facts jsonb;
BEGIN
  SELECT * INTO STRICT c FROM combat_consumer_private.narrative_claims WHERE id=p_claim;
  SELECT * INTO STRICT activity FROM combat_consumer_private.activities WHERE session_id=c.session_id;
  SELECT round_no INTO STRICT current_round FROM public.combat_v2_rounds WHERE id=c.round_id;
  SELECT * INTO STRICT place FROM public.locations WHERE id=activity.location_id;
  IF c.context_payload->>'genere' NOT IN('confronto','rinuncia','azione_risolta') THEN RAISE EXCEPTION 'scene_kind_unsupported'; END IF;
  SELECT jsonb_agg(jsonb_build_object('id',m.actor_id,'name',ch.name,'kind','PG','persona',null,'may_speak',false) ORDER BY m.actor_id)
    INTO actors FROM combat_consumer_private.members m JOIN public.characters ch ON ch.id=m.character_id
    WHERE m.session_id=c.session_id;
  IF jsonb_array_length(actors) IS DISTINCT FROM 2 THEN RAISE EXCEPTION 'scene_current_consumer_roster_unsupported'; END IF;
  -- La descrizione del luogo è ambientazione pubblica. Event_note esclusa: nessuna nuova policy implicita.
  IF nullif(btrim(place.description),'') IS NOT NULL THEN
    sources:=sources||jsonb_build_array(jsonb_build_object('id','location:'||place.id,'session_id',c.session_id,
      'round_id',c.round_id,'kind','setting','actor_id',null,'sequence',current_round,'body',place.description,
      'sha256',encode(extensions.digest(convert_to(place.description,'UTF8'),'sha256'),'hex'),'visibility','public','complete',true));
  END IF;
  FOR row IN
    SELECT d.id,d.actor_id,d.kind,m.id message_id,m.body,m.location_id,m.character_id,l.message_sha256,mem.character_id expected_character
    FROM public.combat_v2_declarations d
    JOIN combat_consumer_private.members mem ON mem.actor_id=d.actor_id AND mem.session_id=c.session_id
    LEFT JOIN combat_consumer_private.declaration_messages l ON l.declaration_id=d.id
    LEFT JOIN public.messages m ON m.id=l.message_id
    WHERE d.round_id=c.round_id AND d.kind IN('attacco','utilita','passa','movimento','difesa','nessuna')
    ORDER BY CASE WHEN d.kind IN('difesa','nessuna') THEN 1 ELSE 0 END,d.id
  LOOP
    IF row.message_id IS NULL OR row.location_id IS DISTINCT FROM activity.location_id
      OR row.character_id IS DISTINCT FROM row.expected_character OR nullif(btrim(row.body),'') IS NULL
      OR public._combat_narrative_sha(row.message_id) IS DISTINCT FROM row.message_sha256 THEN RAISE EXCEPTION 'scene_current_source_invalid'; END IF;
    role_count:=role_count+1;
    actions:=actions||jsonb_build_array(jsonb_build_object('actor_id',row.actor_id,
      'role',CASE WHEN row.kind IN('difesa','nessuna') THEN 'difesa' ELSE 'azione' END,'source_id',row.message_id));
    body_sha:=encode(extensions.digest(convert_to(row.body,'UTF8'),'sha256'),'hex');
    sources:=sources||jsonb_build_array(jsonb_build_object('id',row.message_id,'session_id',c.session_id,'round_id',c.round_id,
      'kind','role','actor_id',row.actor_id,'sequence',current_round,'body',row.body,'sha256',body_sha,'visibility','public','complete',true));
  END LOOP;
  IF role_count<>(CASE WHEN c.context_payload->>'genere'='confronto' OR c.context_payload->>'reazione' IS NOT NULL THEN 2 ELSE 1 END) THEN
    RAISE EXCEPTION 'scene_current_actions_incomplete'; END IF;
  -- Proiezione narrativa già prodotta dal server: nessuna lettura di mechanics_snapshot o ricalcolo.
  facts:=c.context_payload-ARRAY['player_reports','gia_visto','ordinary','model'];
  SELECT count(*) INTO prior_count FROM public.combat_v2_narratives n JOIN public.combat_v2_rounds r ON r.id=n.round_id
    WHERE r.session_id=c.session_id AND r.round_no<current_round AND r.state='narrato';
  snap:=jsonb_build_object('schema_version','combat-scene/1','session_id',c.session_id,'round_id',c.round_id,
    'report_sha256',c.report_sha256,'control_version',c.control_version,'location',place.name,
    'actors',actors,'actions',actions,'resolved_facts',facts::text,'sources',sources,
    'selection',jsonb_build_object('max_input_bytes',49152,'previous_available',prior_count,'previous_included',0));
  IF octet_length(snap::text)>49152 THEN RAISE EXCEPTION 'scene_required_context_overflow'; END IF;
  FOR row IN SELECT n.id,n.round_id,n.body,r.round_no FROM public.combat_v2_narratives n
    JOIN public.combat_v2_rounds r ON r.id=n.round_id WHERE r.session_id=c.session_id AND r.round_no<current_round
    AND r.state='narrato' ORDER BY r.round_no DESC,n.id
  LOOP
    candidate:=jsonb_set(snap,'{sources}',(snap->'sources')||jsonb_build_array(jsonb_build_object('id',row.id,
      'session_id',c.session_id,'round_id',row.round_id,'kind','fato','actor_id',null,'sequence',row.round_no,'body',row.body,
      'sha256',encode(extensions.digest(convert_to(row.body,'UTF8'),'sha256'),'hex'),'visibility','public','complete',true)));
    candidate:=jsonb_set(candidate,'{selection,previous_included}',to_jsonb(included+1));
    EXIT WHEN octet_length(candidate::text)>49152;
    included:=included+1; snap:=candidate;
  END LOOP;
  RETURN snap;
END $function$

CREATE OR REPLACE FUNCTION combat_panel_private.narrative_ordinary_context(p_round uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c combat_consumer_private.activities%ROWTYPE; d public.combat_v2_declarations%ROWTYPE;
 defense public.combat_v2_declarations%ROWTYPE; source public.characters%ROWTYPE; target public.characters%ROWTYPE;
 link combat_consumer_private.declaration_messages%ROWTYPE; facts jsonb; reports jsonb; place text; prior text;
 masked boolean; moved boolean; source_body uuid; target_body uuid; technique text;
BEGIN
 SELECT * INTO STRICT c FROM combat_consumer_private.activities WHERE exchange_id=p_round AND phase='resolved';
 IF NOT EXISTS(SELECT 1 FROM public.combat_v2_round_reports WHERE round_id=p_round AND narration_state='attesa') THEN
   RAISE EXCEPTION 'ordinary_report_not_ready'; END IF;
 SELECT * INTO STRICT d FROM public.combat_v2_declarations
   WHERE round_id=p_round AND kind IN ('attacco','utilita','passa','movimento');
 facts:=combat_panel_private.narrative_declaration_facts(d.id);
 IF NOT combat_consumer_private.narrative_declaration_supported(d.id) THEN
   RAISE EXCEPTION 'ordinary_narrative_source_not_ready';
 END IF;
 SELECT ch.* INTO STRICT source FROM public.characters ch JOIN combat_consumer_private.members m ON m.character_id=ch.id
   WHERE m.session_id=c.session_id AND m.actor_id=d.actor_id;
 SELECT ch.* INTO STRICT target FROM public.characters ch JOIN combat_consumer_private.members m ON m.character_id=ch.id
   WHERE m.session_id=c.session_id AND m.actor_id<>d.actor_id;
 IF nullif(btrim(source.name),'') IS NULL OR nullif(btrim(target.name),'') IS NULL THEN
   RAISE EXCEPTION 'ordinary_narrative_projection_missing'; END IF;
 source_body:=coalesce((SELECT companion_actor_id FROM clan_marionettisti_private.offensive_profiles WHERE declaration_id=d.id),d.actor_id);
 target_body:=coalesce(d.target_actor_id,(SELECT actor_id FROM combat_consumer_private.members WHERE session_id=c.session_id AND actor_id<>d.actor_id));
 SELECT name INTO STRICT place FROM public.locations WHERE id=c.location_id;
 SELECT n.body INTO prior FROM public.combat_v2_narratives n JOIN public.combat_v2_rounds r ON r.id=n.round_id
   WHERE r.session_id=c.session_id AND r.id<>p_round AND r.state='narrato' ORDER BY r.round_no DESC LIMIT 1;
 SELECT * INTO STRICT link FROM combat_consumer_private.declaration_messages WHERE declaration_id=d.id;
 reports:=jsonb_build_object('attack',public._combat_narrative_report(link.message_id,link.message_sha256,c.location_id,source.id));
 IF d.kind='attacco' THEN
   SELECT * INTO STRICT defense FROM public.combat_v2_declarations WHERE parent_attack_id=d.id AND kind IN ('difesa','nessuna');
   SELECT * INTO STRICT link FROM combat_consumer_private.declaration_messages WHERE declaration_id=defense.id;
   reports:=reports||jsonb_build_object('defense',public._combat_narrative_report(link.message_id,link.message_sha256,c.location_id,target.id));
 END IF;
 -- Le distanze reali e il movimento dell'originale non sono fatti pubblici
 -- durante il mascheramento. La sola presenza/risoluzione delle copie non li rivela.
 masked:=facts ? 'multiplication_created' OR facts ? 'clone_events' OR EXISTS(
   SELECT 1 FROM combat_panel_private.multiplication_formations f WHERE f.session_id=c.session_id
     AND f.actor_id IN(d.actor_id,target_body) AND (f.state='active' OR EXISTS(
       SELECT 1 FROM combat_panel_private.multiplication_resolutions mr JOIN public.combat_v2_attack_targets t ON t.id=mr.attack_target_id
       WHERE mr.formation_id=f.id AND t.attack_declaration_id=d.id)));
 moved:=EXISTS(SELECT 1 FROM combat_spatial.spatial_events e WHERE e.actor_id=source_body
   AND e.event_kind='movement_settled' AND (e.after_state->>'d_eff_m')::numeric>0
   AND (e.root_id=d.request_key OR EXISTS(SELECT 1 FROM combat_consumer_private.offers o WHERE o.id=e.root_id AND o.exchange_id=p_round)));
 technique:=CASE WHEN facts ? 'clone_creation' THEN 'Clone di Sabbia'
   WHEN d.kind='passa' THEN 'Conclusione del turno senza altra azione'
   WHEN d.kind='movimento' THEN 'Spostamento'
   WHEN facts->'result' ? 'escape' THEN 'Tenta di liberarti'
   WHEN facts ? 'multiplication_created' THEN 'Moltiplicazione del corpo'
   WHEN source_body<>d.actor_id THEN 'Marionetta da Combattimento: arto rinforzato contundente, controllato tramite Fili di Chakra'
   ELSE 'Colpo a mani nude' END;
 RETURN jsonb_build_object('ordinary',true,'genere','azione_risolta','non_offensivo',d.kind<>'attacco',
   'autore',jsonb_build_object('nome',source.name,'sesso',source.sex),
   'testimone',CASE WHEN EXISTS(SELECT 1 FROM public.combat_v2_actors WHERE id=target_body AND companion_id IS NOT NULL)
      THEN jsonb_build_object('nome','Marionetta','sesso',null) ELSE jsonb_build_object('nome',target.name,'sesso',target.sex) END,
   'luogo',place,'tecnica',technique,'fatti',facts,
   'movimento',CASE WHEN masked THEN 'non_esposto' WHEN moved THEN 'avvenuto' ELSE 'assente' END,
   'reazione',CASE WHEN d.kind='attacco' THEN defense.sanitized_intent->>'reaction' ELSE NULL END,
   'player_reports',reports,'gia_visto',left(coalesce(prior,''),400),'model','gpt-5.6-luna');
END $function$

CREATE OR REPLACE FUNCTION combat_panel_private.narrative_declaration_facts(p_declaration uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.combat_v2_declarations%ROWTYPE; f combat_panel_private.multiplication_formations%ROWTYPE;
 t public.combat_v2_attack_targets%ROWTYPE; facts jsonb; targets jsonb:='[]'::jsonb;
BEGIN
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=p_declaration;
 IF d.state<>'risolta' THEN
   RAISE EXCEPTION 'panel_narrative_declaration_unresolved' USING ERRCODE='55000'; END IF;
 facts:=jsonb_build_object('schema_version','combat-narrative-facts/1','kind',d.kind,
   'result',combat_panel_private.narrative_outcome_facts(d.outcome));
 SELECT * INTO f FROM combat_panel_private.multiplication_formations WHERE declaration_id=d.id;
 IF FOUND THEN
   -- Soltanto il modo dichiarato, immutabile; mai stato attuale o figura originale.
   facts:=facts||jsonb_build_object('multiplication_created',jsonb_build_object('mode',f.mode));
 END IF;
 IF d.kind='attacco' THEN
   FOR t IN SELECT * FROM public.combat_v2_attack_targets WHERE attack_declaration_id=d.id ORDER BY ordinal LOOP
     IF t.state NOT IN ('risolta','superflua') THEN
       RAISE EXCEPTION 'panel_narrative_target_unresolved' USING ERRCODE='55000'; END IF;
     targets:=targets||jsonb_build_array(jsonb_build_object('ordinal',t.ordinal,
       'result',CASE WHEN t.state='superflua' THEN jsonb_build_object('attack_result','not_executed')
         ELSE combat_panel_private.narrative_outcome_facts(t.outcome) END));
   END LOOP;
   facts:=facts||jsonb_build_object('targets',targets);
 END IF;
 RETURN facts||combat_panel_private.narrative_clone_facts(d.id);
END $function$

CREATE OR REPLACE FUNCTION combat_panel_private.narrative_clone_facts(p_declaration uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.combat_v2_declarations%ROWTYPE; witness uuid; payload jsonb;
 result jsonb:='{}'::jsonb; events jsonb:='[]'::jsonb; e record;
BEGIN
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=p_declaration;
 IF d.state<>'risolta' THEN RAISE EXCEPTION 'clone_narrative_unresolved'; END IF;
 payload:=d.outcome->'sabaku_clone';
 IF payload IS NULL AND NOT EXISTS(SELECT 1 FROM clan_sabaku_private.clone_captures WHERE round_id=d.round_id) THEN RETURN result; END IF;
 SELECT m.actor_id INTO STRICT witness FROM combat_consumer_private.members m
   JOIN public.combat_v2_rounds r ON r.session_id=m.session_id
   WHERE r.id=d.round_id AND m.actor_id<>d.actor_id;
 IF payload IS NOT NULL THEN
   IF d.kind<>'utilita' OR payload->>'schema_version' IS DISTINCT FROM 'sabaku-clone/1'
     OR jsonb_typeof(payload->'created') IS DISTINCT FROM 'boolean' THEN
     RAISE EXCEPTION 'clone_narrative_creation_invalid'; END IF;
   IF (payload->>'created')::boolean THEN
     IF NOT EXISTS(SELECT 1 FROM clan_sabaku_private.clones c WHERE c.declaration_id=d.id
       AND c.id=(payload->>'clone_id')::uuid AND c.actor_id=d.actor_id AND c.created_round_id=d.round_id) THEN
       RAISE EXCEPTION 'clone_narrative_creation_missing'; END IF;
     result:=jsonb_build_object('clone_creation',jsonb_build_object('created',true));
   ELSE
     IF payload->>'reason' IS NULL OR payload->>'reason' NOT IN
       ('owner_inoperative','owner_absent','innata_off','placement_changed','clone_already_active','sand_unavailable') THEN
       RAISE EXCEPTION 'clone_narrative_creation_reason_invalid'; END IF;
     result:=jsonb_build_object('clone_creation',jsonb_build_object('created',false,'reason',payload->'reason'));
   END IF;
 END IF;
 FOR e IN SELECT cc.*,c.actor_id AS owner_actor FROM clan_sabaku_private.clone_captures cc
   JOIN clan_sabaku_private.clones c ON c.id=cc.clone_id
   WHERE cc.round_id=d.round_id ORDER BY cc.created_at,cc.id LOOP
   IF e.owner_actor NOT IN(d.actor_id,witness) OR e.target_actor_id NOT IN(d.actor_id,witness)
     OR e.owner_actor=e.target_actor_id OR e.result->>'schema_version' IS DISTINCT FROM 'sabaku-clone-capture/1'
     OR e.result->'damage' IS DISTINCT FROM '0'::jsonb OR jsonb_typeof(e.result->'success') IS DISTINCT FROM 'boolean'
     OR e.result->'copy_hit' IS DISTINCT FROM to_jsonb(e.copy_hit)
     OR (e.copy_hit AND (e.result->>'success')::boolean) THEN
     RAISE EXCEPTION 'clone_narrative_capture_invalid'; END IF;
   events:=events||jsonb_build_array(jsonb_build_object(
     'owner',CASE WHEN e.owner_actor=d.actor_id THEN 'author' ELSE 'witness' END,
     'target',CASE WHEN e.target_actor_id=d.actor_id THEN 'author' ELSE 'witness' END,
     'trigger',e.trigger_kind,
     'outcome',CASE WHEN e.copy_hit THEN 'copy_triggered' WHEN (e.result->>'success')::boolean THEN 'held' ELSE 'capture_failed' END));
 END LOOP;
 IF jsonb_array_length(events)>0 THEN result:=result||jsonb_build_object('clone_events',events); END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_actor_profile(p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; s public.combat_v2_sessions%ROWTYPE;
 ctx jsonb; ability jsonb; rank_name text; nij numeric; chakra numeric; reserved numeric;
 copy_cap integer; options jsonb; rid uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'panel_authentication_required' USING ERRCODE='28000'; END IF;
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=p_actor AND controller_user=auth.uid()
   AND companion_id IS NULL AND state='attivo';
 IF a.id IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO s FROM public.combat_v2_sessions WHERE id=a.session_id AND closed_at IS NULL AND state='in_corso';
 IF s.id IS NULL THEN RETURN NULL; END IF;
 ctx:=combat_panel_private.owner_turn_context(a.id);
 IF ctx IS NULL OR ctx->>'activity_kind' NOT IN ('ordinary_v2','master_v2')
   OR NOT coalesce((ctx->>'can_move')::boolean,false) THEN RETURN NULL; END IF;
 rid:=(ctx->>'round_id')::uuid;
 IF rid IS NULL OR ctx->>'personal_turn_id' IS NULL OR EXISTS(
   SELECT 1 FROM public.combat_v2_declarations WHERE round_id=rid AND actor_id=a.id
     AND kind IN ('attacco','movimento','utilita','passa')) THEN RETURN NULL; END IF;
 IF combat_panel_private.access_reason(s.location_id,ctx->>'activity_kind') IS NOT NULL THEN RETURN NULL; END IF;
 ability:=public.combat_v2_actor_ability(a.id,'jutsu','c6e31b7b-38fe-4b4f-b3c7-05f3e922d193',false);
 IF ability IS NULL THEN RETURN NULL; END IF;
 -- La guardia Fili resta quella rilasciata: nessuna eccezione Moltiplicazione.
 BEGIN
   PERFORM clan_marionettisti_private.assert_jutsu_source(a.id,'jutsu','c6e31b7b-38fe-4b4f-b3c7-05f3e922d193');
 EXCEPTION WHEN SQLSTATE '22023' THEN
   IF SQLERRM='fili_other_jutsu_unavailable' THEN RETURN NULL; ELSE RAISE; END IF;
 END;
 IF ability->>'usage' IS DISTINCT FROM 'principale'
   OR ability->'diversivo' IS DISTINCT FROM 'true'::jsonb
   OR ability->'chakra_cost' IS DISTINCT FROM '10'::jsonb THEN
   RAISE EXCEPTION 'panel_multiplication_catalog_changed' USING ERRCODE='22023'; END IF;
 IF a.actor_kind='pg' THEN
   SELECT c.rank INTO rank_name FROM public.characters c WHERE c.id=a.character_id AND c.user_id=auth.uid();
   IF rank_name IS NULL OR rank_name NOT IN ('Deshi','Genin','Chunin','Jonin','Jonin Speciale','Kage','Sannin') THEN
     RAISE EXCEPTION 'panel_multiplication_rank_unavailable' USING ERRCODE='22023'; END IF;
 ELSIF a.actor_kind='png' THEN
   -- Il grado D..S non viene convertito in un rango PG. L'istanza
   -- registrata fornisce lo snapshot server e il Ninjutsu della formula.
   IF NOT EXISTS(SELECT 1 FROM public.combat_v2_png_instances i
     WHERE i.id=a.png_instance_id AND i.session_id=a.session_id) THEN
     RAISE EXCEPTION 'panel_multiplication_npc_source_unavailable' USING ERRCODE='22023'; END IF;
 ELSE RAISE EXCEPTION 'panel_multiplication_actor_kind_invalid' USING ERRCODE='22023';
 END IF;
 IF jsonb_typeof(a.mechanics_snapshot->'ninjutsu') IS DISTINCT FROM 'number'
   OR jsonb_typeof(a.mechanics_snapshot->'chakra') IS DISTINCT FROM 'number' THEN
   RAISE EXCEPTION 'panel_multiplication_resources_invalid' USING ERRCODE='22023'; END IF;
 nij:=(a.mechanics_snapshot->>'ninjutsu')::numeric; chakra:=(a.mechanics_snapshot->>'chakra')::numeric;
 IF nij<0 OR nij<>trunc(nij) OR nij>2147483647 OR chakra<0
   OR nij IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)
   OR chakra IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) THEN
   RAISE EXCEPTION 'panel_multiplication_resources_invalid' USING ERRCODE='22023'; END IF;
 copy_cap:=CASE WHEN a.actor_kind='pg' THEN public._copie_cap(nij::integer,rank_name)
   ELSE nij::integer/10 END;
 SELECT coalesce(sum((d.cost_snapshot->>'chakra')::numeric),0) INTO reserved
   FROM public.combat_v2_declarations d WHERE d.round_id=rid AND d.actor_id=a.id;
 IF reserved<0 THEN RAISE EXCEPTION 'panel_multiplication_cost_snapshot_invalid' USING ERRCODE='22023'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('copies',n,'chakra_cost',10+5*n) ORDER BY n),'[]'::jsonb)
   INTO options FROM generate_series(1,greatest(0,least(copy_cap,floor((chakra-reserved-10)/5)))::integer) n;
 RETURN jsonb_build_object('schema_version','combat-multiplication-profile/2',
   'activity_kind',ctx->'activity_kind','session_id',s.id,'round_id',rid,
   'personal_turn_id',ctx->'personal_turn_id','actor_id',a.id,'controller_version',a.controller_version,
   'ability_id','c6e31b7b-38fe-4b4f-b3c7-05f3e922d193','base_cost',10,'per_copy_cost',5,
   'copy_cap',copy_cap,'available',jsonb_array_length(options)>0,'copy_options',options);
END $function$

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_bind_declaration(p_declaration uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.combat_v2_declarations%ROWTYPE; plan combat_panel_private.multiplication_declaration_plans%ROWTYPE; fid uuid;
BEGIN
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=p_declaration;
 SELECT * INTO plan FROM combat_panel_private.multiplication_declaration_plans WHERE request_key=d.request_key FOR UPDATE;
 IF plan.request_key IS NULL THEN RETURN; END IF;
 IF plan.declaration_id=d.id THEN RETURN; END IF;
 IF plan.declaration_id IS NOT NULL OR plan.prepared_transaction<>txid_current() OR plan.actor_id<>d.actor_id
   OR plan.round_id<>d.round_id OR plan.principal_user<>d.controller_user_snapshot
   OR plan.controller_version<>d.controller_version_snapshot OR (d.cost_snapshot->>'chakra')::integer<>plan.chakra_cost THEN
   RAISE EXCEPTION 'panel_multiplication_binding_mismatch' USING ERRCODE='42501'; END IF;
 INSERT INTO combat_panel_private.multiplication_formations(session_id,round_id,actor_id,declaration_id,instance_id,
   source_body_version,mode,copy_count,copy_cap,figures,original_index)
 SELECT r.session_id,d.round_id,d.actor_id,d.id,plan.instance_id,plan.source_body_version,
   plan.mode,plan.copies,plan.copy_cap,plan.figures,plan.original_index FROM public.combat_v2_rounds r WHERE r.id=d.round_id
 RETURNING id INTO fid;
 IF plan.movement_m>0 THEN
   INSERT INTO combat_panel_private.master_movement_receipts(declaration_id,round_id,owner_actor_id,body_actor_id,spatial_event_id,distance_m)
   VALUES(d.id,d.round_id,d.actor_id,d.actor_id,plan.movement_event_id,plan.movement_m);
 END IF;
 UPDATE combat_panel_private.multiplication_declaration_plans SET declaration_id=d.id,formation_id=fid WHERE request_key=plan.request_key;
END $function$

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_release(p_clone uuid, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c clan_sabaku_private.clones%ROWTYPE;
BEGIN
 SELECT * INTO STRICT c FROM clan_sabaku_private.clones WHERE id=p_clone;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=c.session_id FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_actors WHERE id=c.actor_id FOR UPDATE;
 PERFORM 1 FROM clan_sabaku_private.reserves WHERE id=c.reserve_id FOR UPDATE;
 SELECT * INTO STRICT c FROM clan_sabaku_private.clones WHERE id=p_clone FOR UPDATE;
 IF c.state='ended' THEN RETURN false; END IF;
 IF p_reason IS NULL OR p_reason NOT IN ('duration','copy_triggered','capture_failed','escaped','owner_inoperative',
   'owner_absent','innata_off','medium_invalid','combat_end','target_inoperative') THEN
   RAISE EXCEPTION 'sabaku_clone_release_reason_invalid' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM clan_sabaku_private.sand_ledger WHERE clone_id=c.id AND event_kind='commit') THEN
   RAISE EXCEPTION 'sabaku_clone_release_without_commit' USING ERRCODE='22023'; END IF;
 UPDATE clan_sabaku_private.reserves SET committed_amount=committed_amount-c.amount,state_version=state_version+1
   WHERE id=c.reserve_id AND committed_amount>=c.amount;
 IF NOT FOUND THEN RAISE EXCEPTION 'sabaku_clone_reserve_commit_drift' USING ERRCODE='22023'; END IF;
 UPDATE clan_sabaku_private.clones SET state='ended',state_version=state_version+1,end_reason=p_reason,ended_at=clock_timestamp() WHERE id=c.id;
 INSERT INTO clan_sabaku_private.sand_ledger(clone_id,event_kind,amount) VALUES(c.id,'release',c.amount);
 PERFORM combat_panel_private.immobilization_release_source(c.declaration_id,
   CASE WHEN p_reason IN ('duration','escaped','copy_triggered','capture_failed') THEN 'source_ended' ELSE 'source_invalid' END);
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_trigger_nearby(p_clone uuid, p_round uuid, p_kind text, p_actor uuid DEFAULT NULL::uuid, p_event uuid DEFAULT NULL::uuid, p_formation_declaration uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c clan_sabaku_private.clones%ROWTYPE; a public.combat_v2_actors%ROWTYPE;
 selected record; capture_id uuid; reason text; copy_hit boolean; velocity numeric; taijutsu numeric;
 entropy bytea; dice integer[]; domain text; capture_result jsonb; effect_id uuid;
BEGIN
 SELECT * INTO STRICT c FROM clan_sabaku_private.clones WHERE id=p_clone;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=c.session_id FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_actors WHERE session_id=c.session_id ORDER BY id FOR UPDATE;
 SELECT * INTO STRICT c FROM clan_sabaku_private.clones WHERE id=c.id FOR UPDATE;
 SELECT id INTO capture_id FROM clan_sabaku_private.clone_captures WHERE clone_id=c.id;
 IF capture_id IS NOT NULL THEN RETURN capture_id; END IF;
 IF c.state<>'armed' THEN RETURN NULL; END IF;
 IF p_kind IS NULL OR p_kind NOT IN ('initial_presence','movement','formation_created')
   OR (p_kind='movement') IS DISTINCT FROM (p_event IS NOT NULL)
   OR (p_kind='formation_created') IS DISTINCT FROM (p_formation_declaration IS NOT NULL)
   OR (p_kind IN ('movement','formation_created') AND p_actor IS NULL)
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds WHERE id=p_round AND session_id=c.session_id) THEN
   RAISE EXCEPTION 'sabaku_clone_trigger_context_invalid' USING ERRCODE='22023'; END IF;
 reason:=clan_sabaku_private.clone_end_reason(c.id);
 IF reason IS NOT NULL THEN PERFORM clan_sabaku_private.clone_release(c.id,reason); RETURN NULL; END IF;
 SELECT * INTO selected FROM clan_sabaku_private.clone_nearby_candidates(c.id,p_actor) LIMIT 1;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=selected.actor_id;
 copy_hit:=false;
 IF selected.formation_id IS NOT NULL THEN
   SELECT selected.figure_index<>f.original_index INTO STRICT copy_hit
     FROM combat_panel_private.multiplication_formations f WHERE f.id=selected.formation_id AND f.state='active';
 END IF;
 capture_id:=gen_random_uuid();
 IF copy_hit THEN
   capture_result:=jsonb_build_object('schema_version','sabaku-clone-capture/1','copy_hit',true,'success',false,'damage',0);
 ELSE
   velocity:=(a.mechanics_snapshot->>'velocita')::numeric;
   taijutsu:=(a.mechanics_snapshot->>'taijutsu')::numeric;
   domain:='combat-v2/sabaku-clone-capture/1:'||c.session_id::text||':'||c.id::text||':'||capture_id::text;
   entropy:=extensions.gen_random_bytes(32);
   dice:=ARRAY[public.combat_v2_derive_d10(entropy,domain,1),public.combat_v2_derive_d10(entropy,domain,2),
     public.combat_v2_derive_d10(entropy,domain,3),public.combat_v2_derive_d10(entropy,domain,4)];
   capture_result:=clan_sabaku_private.clone_capture_result(c.source_kekkei_genkai,c.source_ninjutsu,velocity,taijutsu,dice);
 END IF;
 INSERT INTO clan_sabaku_private.clone_captures(id,clone_id,round_id,target_actor_id,trigger_kind,trigger_event_id,
   trigger_declaration_id,formation_id,selected_index,copy_hit,target_velocity,target_taijutsu,entropy,dice,result)
 VALUES(capture_id,c.id,p_round,a.id,p_kind,p_event,p_formation_declaration,selected.formation_id,selected.figure_index,
   copy_hit,velocity,taijutsu,entropy,dice,capture_result);
 IF copy_hit THEN PERFORM clan_sabaku_private.clone_release(c.id,'copy_triggered');
 ELSIF (capture_result->>'success')::boolean THEN
   effect_id:=clan_sabaku_private.clone_apply_immobilization(capture_id);
   IF effect_id IS NULL THEN RAISE EXCEPTION 'sabaku_clone_hold_missing' USING ERRCODE='22023'; END IF;
   UPDATE clan_sabaku_private.clones SET state='holding',state_version=state_version+1 WHERE id=c.id;
 ELSE PERFORM clan_sabaku_private.clone_release(c.id,'capture_failed'); END IF;
 RETURN capture_id;
END $function$

CREATE OR REPLACE FUNCTION combat_consumer_private.narrative_declaration_supported(p_declaration uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.combat_v2_declarations%ROWTYPE; facts jsonb; sid uuid;
BEGIN
 SELECT * INTO d FROM public.combat_v2_declarations WHERE id=p_declaration;
 IF d.id IS NULL OR d.state IS DISTINCT FROM 'risolta' THEN RETURN false; END IF;
 IF d.kind='attacco' THEN
   RETURN clan_marionettisti_private.narrative_attack_allowed(d.id);
 END IF;
 SELECT session_id INTO sid FROM public.combat_v2_rounds WHERE id=d.round_id;
 IF sid IS NULL THEN RETURN false; END IF;
 IF d.kind='passa' THEN
   RETURN clan_marionettisti_private.is_dedicated_scene(sid)
     AND coalesce((SELECT rinuncia_enabled FROM clan_marionettisti_private.release_gate WHERE singleton),false);
 END IF;
 IF d.kind NOT IN ('utilita','movimento') THEN RETURN false; END IF;
 -- Le utility già supportate entrano soltanto dal contesto Staff protetto.
 -- Accessi/roster/provider restano verificati da narrative_allowed nel dispatch/acquire.
 IF NOT EXISTS(SELECT 1 FROM combat_consumer_private.activities c
   JOIN public.combat_v2_sessions s ON s.id=c.session_id
   JOIN public.locations l ON l.id=c.location_id
   WHERE c.session_id=sid AND c.exchange_id=d.round_id AND c.phase='resolved'
     AND l.is_test AND c.policy_id='staff_test_no_persistent_resources_v1'
     AND s.source_kind='ordinary' AND s.location_id=c.location_id
     AND NOT public.combat_v2_values_written(s.id)) THEN RETURN false; END IF;
 facts:=combat_panel_private.narrative_declaration_facts(d.id);
 RETURN CASE WHEN d.kind='utilita' THEN
   (facts ? 'multiplication_created' OR facts->'result' ? 'escape' OR facts ? 'clone_creation')
   ELSE facts ? 'clone_events' END;
END $function$

